  /** helper function to set the values of all input ports.
   * @param request_facts payload for data port request_facts
   * @param preparation_facts payload for data port preparation_facts
   * @param equipment_facts payload for data port equipment_facts
   * @param recovery_frame payload for data port recovery_frame
   */
  def put_concrete_inputs(request_facts : EIT_Acquisition_Supervisor.RequestFactsRecord,
                          preparation_facts : EIT_Acquisition_Supervisor.PreparationFacts.Type,
                          equipment_facts : EIT_Acquisition_Supervisor.EquipmentFacts.Type,
                          recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    put_request_facts(request_facts)
    put_preparation_facts(preparation_facts)
    put_equipment_facts(equipment_facts)
    put_recovery_frame(recovery_frame)
  }


  /** helper function to check StartFeasibilityOwner_acquisition_process_start_feasibility's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param start_feasibility method that will be called with the value of the outgoing data
   *        port 'start_feasibility'.
   */
  def check_concrete_output(start_feasibility: EIT_Acquisition_Supervisor.StartFeasibility.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val start_feasibilityValue: EIT_Acquisition_Supervisor.StartFeasibility.Type = get_start_feasibility().get
    if(!start_feasibility(start_feasibilityValue)) {
      testFailures = testFailures :+ st"'start_feasibility' did not match expected: value of the outgoing data port is ${start_feasibilityValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


