  // getter for out DataPort
  def get_start_feasibility(): Option[EIT_Acquisition_Supervisor.StartFeasibility.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.StartFeasibility.Type] = get_start_feasibility_payload() match {
      case Some(EIT_Acquisition_Supervisor.StartFeasibility_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port start_feasibility.  Expecting 'EIT_Acquisition_Supervisor.StartFeasibility_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.StartFeasibility.Type]()
    }
    return value
